def _decorate_preset(item):
    import re
    result = dict(item)
    html = result.get("html", "")
    preset_id = result.get("id", "")
    base = {
        "countdown": "☕", "cars": "🚘", "cats-repair": "⚙️", "loading": "🏥",
        "auto-service": "🔧", "beauty-salon": "💗", "phone-repair": "📱",
        "medical-diagnostics": "🩺",
    }.get(preset_id, "✨")

    def emoji_for(content):
        plain = re.sub(r"<[^>]*>", " ", content).lower()
        if any(word in plain for word in ("цена", "стоимость", "прайс", "₽")): return "💳"
        if any(word in plain for word in ("адрес", "контакт", "связ", "телефон")): return "📍"
        if any(word in plain for word in ("запис", "заяв", "время", "обратн")): return "🗓️"
        if any(word in plain for word in ("гарант", "провер", "довер", "безопас")): return "🛡️"
        if any(word in plain for word in ("машин", "автомоб", "наличи", "каталог")): return "🚘"
        if any(word in plain for word in ("анализ", "диагност", "обслед", "приём", "здоров")): return "🩺"
        if any(word in plain for word in ("волос", "маникюр", "красот", "окраш")): return "💗"
        if any(word in plain for word in ("мастер", "команд", "врач", "специалист")):
            return "👩‍⚕️" if preset_id in ("loading", "medical-diagnostics") else "👩‍🔧" if preset_id in ("auto-service", "phone-repair") else "💇"
        if any(word in plain for word in ("услуг", "направлен", "ремонт", "обслуж")):
            return {"cars":"🚘","auto-service":"🔧","beauty-salon":"💇","phone-repair":"🪛",
                    "loading":"🩺","medical-diagnostics":"🩺","countdown":"☕","cats-repair":"⚙️"}.get(preset_id, base)
        return base

    def decorate(match):
        tag, attrs, content = match.group(1), match.group(2), match.group(3)
        emoji = emoji_for(content)
        return f'<{tag}{attrs}><span class="preset-heading-emoji" aria-hidden="true">{emoji}</span>{content}</{tag}>'

    html = re.sub(r"<(h1|h2|h3)(\b[^>]*)>(.*?)</\1>", decorate, html, flags=re.I | re.S)
    style = (
        '<style>.preset-heading-emoji{display:block;font-family:system-ui,sans-serif;'
        'font-size:22px;line-height:1;margin:0 0 9px;letter-spacing:0;'
        'filter:drop-shadow(0 2px 7px #0002)}h1 .preset-heading-emoji{font-size:25px;'
        'margin-bottom:13px}h2 .preset-heading-emoji{font-size:20px}'
        'h3 .preset-heading-emoji{font-size:17px;margin-bottom:7px}</style>'
    )
    if "</head>" in html:
        html = html.replace("</head>", style + "</head>", 1)
    result["html"] = html
    return result
